#include <random>
#include <bits/stdc++.h>
#include <json.hpp>
using namespace std;using J=nlohmann::json;using M=map<int,long double>;
void axpy(M&a,const M&b,long double q){for(auto[k,x]:b){a[k]+=q*x;if(fabsl(a[k])<1e-10)a.erase(k);}}
struct B{int p,s;M r,co;};struct P{int s;M co;long double gain;};
int main(int ac,char**av){J c;ifstream(av[1])>>c;map<int,M>resp;map<int,int>dims;for(auto it=c["response"].begin();it!=c["response"].end();it++)for(auto jt=it.value().begin();jt!=it.value().end();jt++)resp[stoi(it.key())][stoi(jt.key())]=jt.value();for(auto it=c["dims"].begin();it!=c["dims"].end();it++)dims[stoi(it.key())]=it.value();long double alpha=.0010035L;auto chi=[&](int r){return r? r*expm1l(alpha*logl(73.L/r)):0.L;};map<int,long double>dc,pg;for(auto[s,d]:dims){dc[s]=chi(1)+chi(d-1)-chi(d);pg[s]=chi(d)-chi(d-1);}mt19937 rng(721119);J plans=J::array();long double global=0;int trials=0;for(auto g:c["groups"]){int ed=g.value("ed",1);for(auto[s,d]:dims){dc[s]=chi(ed)+chi(d-ed)-chi(d);pg[s]=chi(d)-chi(d-ed);}vector<int>mem=g["members"];long double best=0;J bj;for(int iter=0;iter<160;iter++){vector<pair<long double,int>>order;for(int s:mem){long double weight=dc[s]+pg[s];if(iter%4==1)weight=dc[s];if(iter%4==2)weight=pg[s];if(iter>0)weight*=.4L+(rng()%10000)/6000.L;order.push_back({weight,s});}sort(order.begin(),order.end());vector<B>basis;vector<P>piv;for(auto[w,s]:order){M r=resp[s],co;for(auto b:basis)if(r.count(b.p)){long double q=r[b.p]/b.r.at(b.p);axpy(r,b.r,-q);axpy(co,b.co,-q);}if(r.empty())piv.push_back({s,co,pg[s]});else{co[s]+=1;basis.push_back({r.begin()->first,s,r,co});}}trials++;bool progress=true;while(progress&&!piv.empty()){progress=false;map<int,int>users;for(auto p:piv)for(auto[s,x]:p.co)users[s]++;int drop=-1;long double saving=0;for(int i=0;i<(int)piv.size();i++){long double freed=0;for(auto[s,x]:piv[i].co)if(users[s]==1)freed+=dc[s];if(freed-piv[i].gain>saving+1e-12L){saving=freed-piv[i].gain;drop=i;}}if(drop>=0){piv.erase(piv.begin()+drop);progress=true;}}set<int>don;long double gain=0;for(auto p:piv){gain+=p.gain;for(auto[s,x]:p.co)don.insert(s);}for(int s:don)gain-=dc[s];if(gain>best+1e-12L){best=gain;J ps=J::array();for(auto p:piv){J cm=J::object();for(auto[s,x]:p.co)cm[to_string(s)]=double(x);ps.push_back({{"pivot",p.s},{"coefficients",cm}});}bj={{"vector",g["vector"]},{"basis",g.value("basis",J::array({g["vector"]}))},{"ed",ed},{"gain",double(gain)},{"pivots",ps},{"donors",don},{"iteration",iter}};}}
if(best>1e-12L){plans.push_back(bj);if(best>global){global=best;cout<<"best "<<g["vector"]<<" ed "<<ed<<" gain "<<double(global)<<" gauges "<<bj["pivots"].size()<<endl;}}}J out={{"source_sha256",c["source_sha256"]},{"trials",trials},{"plans",plans},{"best_gain",double(global)},{"scope","All rank-one directions and pairwise intersections of first-helper frames; randomized weighted rational-response basis nominations; float only, exact response/kernel and paid physical admission required"}};ofstream(av[2])<<out.dump(2)<<endl;cout<<"plans "<<plans.size()<<" trials "<<trials<<" best "<<double(global)<<endl;}

